<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\TenantLoginProviderAccountLinkPolicyVO;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderAccountLinkPolicyOptions;

final class TenantLoginProviderAccountLinkPolicyVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = TenantLoginProviderAccountLinkPolicyOptions::NONE;
        $ref = TenantLoginProviderAccountLinkPolicyVO::from($value);
        $this->assertEquals(TenantLoginProviderAccountLinkPolicyOptions::NONE, $ref->value());
        $other = TenantLoginProviderAccountLinkPolicyVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = TenantLoginProviderAccountLinkPolicyVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = TenantLoginProviderAccountLinkPolicyVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(TenantLoginProviderAccountLinkPolicyVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = TenantLoginProviderAccountLinkPolicyVO::from(TenantLoginProviderAccountLinkPolicyOptions::NONE);
        $same = TenantLoginProviderAccountLinkPolicyVO::from(TenantLoginProviderAccountLinkPolicyOptions::NONE);
        $other = TenantLoginProviderAccountLinkPolicyVO::from(TenantLoginProviderAccountLinkPolicyOptions::VERIFIED_EMAIL);
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
}
